          code: "/*\n * ======================== ENTITY-RELATIONSHIP DIAGRAM ========================\n *\n * +-------------------------+          1         0..* +-------------------------------+\n * |         users           |-------------------------|          short_urls           |\n * +-------------------------+                         +-------------------------------+\n * | PK user_id (BIGINT)     |                         | PK short_code (VARCHAR(16))   |\n * |    email (VARCHAR(255)) |                         |    id_num (BIGINT)            |\n * |    api_key_hash (CHAR)  |                         |    long_url (VARCHAR(2048))   |\n * |    tier (ENUM)          |                         | FK user_id (BIGINT, NULLABLE) |\n * |    created_at (INSTANT) |                         |    redirect_type (SMALLINT)   |\n * +-------------------------+                         |    created_at (INSTANT)       |\n *                                                     |    expires_at (INSTANT)       |\n *                                                     |    is_active (BOOLEAN)        |\n *                                                     +---------------+---------------+\n *                                                                     | 1\n *                                                                     |\n *                                                                     | 0..* (Async via Kafka)\n *                                                     +---------------+---------------+\n *                                                     |    click_events (ClickHouse)  |\n *                                                     +-------------------------------+\n *                                                     | PK event_id (UUID)            |\n *                                                     |    short_code (VARCHAR(16))   |\n *                                                     |    clicked_at (INSTANT)       |\n *                                                     |    country_code (CHAR(2))     |\n *                                                     |    user_agent (VARCHAR(512))  |\n *                                                     +-------------------------------+\n */\n\npackage com.sdi.urlshortener.domain;\n\nimport java.time.Instant;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.Size;\nimport org.springframework.http.*;\nimport org.springframework.web.bind.annotation.*;\nimport java.net.URI;\n\n// --- Database Entity (Cassandra / DynamoDB Table Model) ---\npublic record ShortUrlEntity(\n    String shortCode,         // Partition Key (7-char Base62 or up to 16-char custom alias)\n    long idNum,               // Underlying 64-bit numeric ID\n    String longUrl,           // Original destination URL\n    Long userId,              // Owner ID (nullable for anonymous links)\n    int redirectType,         // 301 or 302\n    Instant createdAt,\n    Instant expiresAt,        // Nullable; mapped to DynamoDB/Cassandra TTL\n    boolean isActive\n) {}\n\n// --- API Request & Response DTOs ---\npublic record CreateShortUrlRequest(\n    @NotBlank @Size(max = 2048) String longUrl,\n    @Size(min = 4, max = 16) String customAlias,\n    Instant expiresAt,\n    Integer redirectType      // Defaults to 302 if null\n) {}\n\npublic record CreateShortUrlResponse(\n    String shortCode,\n    String shortUrl,\n    String longUrl,\n    Instant expiresAt\n) {}\n\n// --- REST Controller ---\n@RestController\npublic class UrlShortenerController {\n\n    private final UrlShortenerService urlService;\n\n    public UrlShortenerController(UrlShortenerService urlService) {\n        this.urlService = urlService;\n    }\n\n    @PostMapping(\"/api/v1/urls\")\n    public ResponseEntity<CreateShortUrlResponse> createShortUrl(\n            @RequestHeader(value = \"X-User-Id\", required = false) Long userId,\n            @RequestBody CreateShortUrlRequest request) {\n        CreateShortUrlResponse response = urlService.shortenUrl(userId, request);\n        return ResponseEntity.status(HttpStatus.CREATED).body(response);\n    }\n\n    @GetMapping(\"/{shortCode:[a-zA-Z0-9_-]{4,16}}\")\n    public ResponseEntity<Void> redirect(\n            @PathVariable String shortCode,\n            @RequestHeader(value = \"User-Agent\", required = false) String userAgent,\n            @RequestHeader(value = \"CF-IPCountry\", required = false) String country) {\n\n        ShortUrlEntity mapping = urlService.resolveShortCode(shortCode, userAgent, country);\n        HttpStatus status = (mapping.redirectType() == 301)\n                ? HttpStatus.MOVED_PERMANENTLY\n                : HttpStatus.FOUND;\n\n        return ResponseEntity.status(status)\n                .location(URI.create(mapping.longUrl()))\n                .header(HttpHeaders.CACHE_CONTROL,\n                        mapping.redirectType() == 301 ? \"public, max-age=86400\" : \"no-cache\")\n                .build();\n    }\n}"
