          title: "Flow 1 (Atomic Redis Lua Token Bucket) & Flow 2 (Java Gateway Filter with Fallback)",
          code: "/*\n * ==================== FLOW 1: ATOMIC REDIS LUA TOKEN BUCKET =========================\n *\n * Gateway Pod -> EVALSHA <script_sha> 1 \"rl:api:user_42\" <capacity> <refill_rate> <now_ms> <cost>\n *   |\n *   +--> [Inside Redis Shard - Single Threaded Atomic Execution]\n *        1. HMGET key \"tokens\" \"last_refill_ms\"\n *        2. delta_sec = max(0, now_ms - last_refill_ms) / 1000.0\n *        3. current_tokens = min(capacity, old_tokens + (delta_sec * refill_rate))\n *        4. if current_tokens >= cost:\n *              current_tokens -= cost\n *              HMSET key \"tokens\" current_tokens \"last_refill_ms\" now_ms\n *              PEXPIRE key ttl_ms\n *              return {1, current_tokens, 0}\n *           else:\n *              retry_ms = ((cost - current_tokens) / refill_rate) * 1000\n *              return {0, current_tokens, retry_ms}\n *\n * ==================== FLOW 2: GATEWAY EXECUTION & CIRCUIT BREAKER ====================\n *\n * Request -> Extract Key -> Match Rule -> Try Redis EVALSHA (Timeout = 5ms)\n *                                            |-- Success -> Set X-RateLimit Headers -> 200 or 429\n *                                            +-- Timeout/Error -> Fallback Local Memory Bucket\n */\n\npackage com.sdi.ratelimiter.service;\n\nimport org.springframework.data.redis.core.StringRedisTemplate;\nimport org.springframework.data.redis.core.script.DefaultRedisScript;\nimport org.springframework.stereotype.Service;\n\nimport java.time.Instant;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.concurrent.ConcurrentHashMap;\n\n@Service\npublic class DistributedTokenBucketLimiter {\n\n    // Atomic Lua Script: executes Token Bucket refill + consume in 1 round-trip\n    private static final String TOKEN_BUCKET_LUA = \"\"\"\n            local key = KEYS[1]\n            local capacity = tonumber(ARGV[1])\n            local refill_rate = tonumber(ARGV[2])\n            local now_ms = tonumber(ARGV[3])\n            local requested = tonumber(ARGV[4])\n\n            local data = redis.call('HMGET', key, 'tokens', 'last_refill_ms')\n            local tokens = tonumber(data[1])\n            local last_refill = tonumber(data[2])\n\n            if tokens == nil then\n                tokens = capacity\n                last_refill = now_ms\n            else\n                local elapsed_sec = math.max(0, now_ms - last_refill) / 1000.0\n                tokens = math.min(capacity, tokens + (elapsed_sec * refill_rate))\n                last_refill = now_ms\n            end\n\n            local allowed = 0\n            local retry_after_ms = 0\n\n            if tokens >= requested then\n                tokens = tokens - requested\n                allowed = 1\n                redis.call('HMSET', key, 'tokens', tokens, 'last_refill_ms', last_refill)\n                local ttl_ms = math.ceil((capacity / refill_rate) * 2000)\n                redis.call('PEXPIRE', key, ttl_ms)\n            else\n                retry_after_ms = math.ceil(((requested - tokens) / refill_rate) * 1000)\n            end\n\n            return { allowed, math.floor(tokens), retry_after_ms }\n            \"\"\";\n\n    private final StringRedisTemplate redisTemplate;\n    private final DefaultRedisScript<List> redisScript;\n    // Fallback local state if Redis cluster is unreachable\n    private final ConcurrentHashMap<String, LocalBucket> fallbackBuckets = new ConcurrentHashMap<>();\n\n    public DistributedTokenBucketLimiter(StringRedisTemplate redisTemplate) {\n        this.redisTemplate = redisTemplate;\n        this.redisScript = new DefaultRedisScript<>(TOKEN_BUCKET_LUA, List.class);\n    }\n\n    @SuppressWarnings(\"unchecked\")\n    public RateLimitDecision evaluate(RateLimitRule rule, String subjectKey, int cost) {\n        String redisKey = \"rl:{\" + rule.ruleId() + \":\" + subjectKey + \"}\";\n        long nowMs = Instant.now().toEpochMilli();\n\n        try {\n            List<Long> result = (List<Long>) redisTemplate.execute(\n                    redisScript,\n                    Collections.singletonList(redisKey),\n                    String.valueOf(rule.bucketCapacity()),\n                    String.valueOf(rule.refillRatePerSec()),\n                    String.valueOf(nowMs),\n                    String.valueOf(cost)\n            );\n\n            boolean allowed = result.get(0) == 1L;\n            long remaining = result.get(1);\n            long retryAfterMs = result.get(2);\n\n            return new RateLimitDecision(\n                    allowed, rule.ruleId(), rule.bucketCapacity(), remaining, retryAfterMs\n            );\n        } catch (Exception redisFailure) {\n            // Graceful degradation: fall back to local in-memory bucket (or fail-open)\n            return evaluateLocalFallback(rule, redisKey, cost, nowMs);\n        }\n    }\n\n    private RateLimitDecision evaluateLocalFallback(\n            RateLimitRule rule, String key, int cost, long nowMs) {\n        LocalBucket bucket = fallbackBuckets.computeIfAbsent(\n                key, k -> new LocalBucket(rule.bucketCapacity(), nowMs));\n        return bucket.tryConsume(rule, cost, nowMs);\n    }\n\n    private static final class LocalBucket {\n        private double tokens;\n        private long lastRefillMs;\n\n        LocalBucket(double tokens, long lastRefillMs) {\n            this.tokens = tokens;\n            this.lastRefillMs = lastRefillMs;\n        }\n\n        synchronized RateLimitDecision tryConsume(RateLimitRule rule, int cost, long nowMs) {\n            double elapsedSec = Math.max(0, nowMs - lastRefillMs) / 1000.0;\n            tokens = Math.min(rule.bucketCapacity(), tokens + elapsedSec * rule.refillRatePerSec());\n            lastRefillMs = nowMs;\n            if (tokens >= cost) {\n                tokens -= cost;\n                return new RateLimitDecision(true, rule.ruleId(), rule.bucketCapacity(), (long) tokens, 0);\n            }\n            long retryMs = (long) (((cost - tokens) / rule.refillRatePerSec()) * 1000);\n            return new RateLimitDecision(false, rule.ruleId(), rule.bucketCapacity(), (long) tokens, retryMs);\n        }\n    }\n}"
