          code: "/*\n * ======================== ENTITY-RELATIONSHIP DIAGRAM ========================\n *\n * +----------------------------------+ 1     150 +----------------------------------+\n * |           ShardNode              |-----------|           VirtualNode            |\n * +----------------------------------+           +----------------------------------+\n * | PK shardId (STRING)              |           | PK tokenHash (UINT32 / INT64)    |\n * |    host (STRING)                 |           | FK shardId (STRING)              |\n * |    port (INT)                    |           |    replicaIndex (INT)            |\n * |    role (ENUM: PRIMARY, REPLICA) |           +----------------------------------+\n * |    status (ENUM: ALIVE, SUSPECT) |\n * +----------------+-----------------+\n *                  | 1\n *                  | hosts 16\n *                  v\n * +----------------------------------+ 1       * +----------------------------------+\n * |          CacheSegment            |-----------|          CacheEntryNode          |\n * +----------------------------------+           +----------------------------------+\n * | PK segmentId (INT 0..15)         |           | PK key (STRING)                  |\n * |    maxBytes (LONG)               |           |    valueBytes (BYTE[])           |\n * |    currentBytes (LONG)           |           |    expireAtMs (LONG)             |\n * |    head (CacheEntryNode)         |           |    version (LONG - for CAS)      |\n * |    tail (CacheEntryNode)         |           |    prev (CacheEntryNode)         |\n * +----------------------------------+           |    next (CacheEntryNode)         |\n *                                                +----------------------------------+\n */\n\npackage com.sdi.cache.core;\n\nimport java.time.Duration;\nimport java.util.Optional;\nimport java.util.function.Supplier;\n\n// --- Cluster Topology Entity ---\npublic record ShardNode(\n    String shardId,\n    String host,\n    int port,\n    boolean isPrimary,\n    String primaryShardId\n) {}\n\n// --- Wire Protocol Command & Response DTOs ---\npublic enum CommandType {\n    GET, SET, DELETE, CAS\n}\n\npublic record CacheCommand(\n    CommandType type,\n    String key,\n    byte[] value,\n    long ttlMs,\n    long expectedVersion\n) {}\n\npublic record CacheResponse(\n    boolean hit,\n    boolean success,\n    byte[] value,\n    long version\n) {}\n\n// --- Internal Doubly-Linked List + Hash Table Entry inside a Cache Shard ---\npublic final class CacheEntryNode {\n    public final String key;\n    public volatile byte[] valueBytes;\n    public volatile long expireAtMs;\n    public volatile long version;\n    public CacheEntryNode prev;\n    public CacheEntryNode next;\n\n    public CacheEntryNode(String key, byte[] valueBytes, long expireAtMs, long version) {\n        this.key = key;\n        this.valueBytes = valueBytes;\n        this.expireAtMs = expireAtMs;\n        this.version = version;\n    }\n\n    public boolean isExpired(long nowMs) {\n        return expireAtMs > 0 && nowMs >= expireAtMs;\n    }\n}\n\n// --- Smart Client SDK Interface ---\npublic interface DistributedCacheClient {\n    Optional<byte[]> get(String key);\n    void set(String key, byte[] value, Duration ttl);\n    boolean compareAndSet(String key, byte[] newValue, long expectedVersion, Duration ttl);\n    void delete(String key);\n\n    /**\n     * Stampede-safe read-through helper: coalesces concurrent misses for the same key\n     * on this JVM into a single loader execution.\n     */\n    byte[] getOrLoad(String key, Duration ttl, Supplier<byte[]> dbLoader);\n}"
