          title: "Entity-Relationship Diagram, Java Entities & Ingestion API",
          code: "/*\n * ======================== ENTITY-RELATIONSHIP DIAGRAM ========================\n *\n * +-------------------------------+ 1      * +-----------------------------------+\n * |      user_preferences         |----------|           user_devices            |\n * +-------------------------------+          +-----------------------------------+\n * | PK user_id (BIGINT)           |          | PK device_id (VARCHAR(64))        |\n * |    email (VARCHAR(255))       |          | FK user_id (BIGINT)               |\n * |    phone_e164 (VARCHAR(20))   |          |    platform (ENUM: IOS, ANDROID)  |\n * |    push_enabled (BOOLEAN)     |          |    push_token (VARCHAR(512))      |\n * |    email_enabled (BOOLEAN)    |          |    is_valid (BOOLEAN)             |\n * |    sms_enabled (BOOLEAN)      |          |    last_active_at (INSTANT)       |\n * |    quiet_start_hr (SMALLINT)  |          +-----------------------------------+\n * |    quiet_end_hr (SMALLINT)    |\n * |    timezone (VARCHAR(64))     |          +-----------------------------------+\n * +---------------+---------------+          |     notification_templates        |\n *                 | 1                        +-----------------------------------+\n *                 |                          | PK template_id (VARCHAR(64))      |\n *                 | 0..*                     | PK locale (VARCHAR(10))           |\n * +---------------+---------------+          |    channel (ENUM)                 |\n * |   notification_logs (Cass.)   |          |    subject_tpl (VARCHAR(255))     |\n * +-------------------------------+          |    body_tpl (TEXT)                |\n * | PK user_id (BIGINT)           |          +-----------------------------------+\n * | CK created_at (TIMESTAMP)     |\n * | CK notification_id (UUID)     |\n * |    idempotency_key (VARCHAR)  |\n * |    channel (ENUM)             |\n * |    priority (ENUM)            |\n * |    status (ENUM: SENT, DLQ)   |\n * |    retry_count (INT)          |\n * +-------------------------------+\n */\n\npackage com.sdi.notification.domain;\n\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport org.springframework.http.*;\nimport org.springframework.web.bind.annotation.*;\n\npublic enum Channel {\n    IOS_PUSH, ANDROID_PUSH, EMAIL, SMS, IN_APP\n}\n\npublic enum Priority {\n    CRITICAL,   // P0: OTPs, Password Resets, Fraud Alerts (Bypasses quiet hours)\n    HIGH,       // P1: Direct messages, Order out-for-delivery\n    BULK        // P2: Weekly digests, Promotional campaigns\n}\n\npublic enum DeliveryStatus {\n    ACCEPTED, QUEUED, SENT, DELIVERED, FAILED_RETRYABLE, DEAD_LETTERED, SUPPRESSED\n}\n\n// --- User Preference & Device Entities ---\npublic record UserPreferenceEntity(\n    long userId,\n    String email,\n    String phoneE164,\n    boolean pushEnabled,\n    boolean emailEnabled,\n    boolean smsEnabled,\n    int quietStartHour,         // e.g., 22 (10 PM local time)\n    int quietEndHour,           // e.g., 8 (8 AM local time)\n    String timezone             // e.g., \"America/Los_Angeles\"\n) {}\n\npublic record DeviceToken(\n    String deviceId,\n    Channel platform,           // IOS_PUSH or ANDROID_PUSH\n    String pushToken\n) {}\n\n// --- API Request & Response DTOs ---\npublic record SendNotificationRequest(\n    String idempotencyKey,      // Mandatory client-generated UUID\n    long userId,\n    Priority priority,\n    Set<Channel> channels,\n    String templateId,\n    String locale,\n    Map<String, String> variables\n) {}\n\npublic record SendNotificationResponse(\n    String notificationId,\n    String idempotencyKey,\n    DeliveryStatus status,\n    List<Channel> scheduledChannels\n) {}\n\n// --- Kafka Envelope Dispatched to Channel Workers ---\npublic record ChannelDispatchEvent(\n    String notificationId,\n    String idempotencyKey,\n    long userId,\n    Channel channel,\n    Priority priority,\n    String targetAddress,       // APNs token, FCM token, Email, or E.164 Phone\n    String templateId,\n    String locale,\n    Map<String, String> variables,\n    int attempt\n) {}\n\n// --- Ingestion REST Controller ---\n@RestController\n@RequestMapping(\"/api/v1/notifications\")\npublic class NotificationController {\n\n    private final NotificationIngestionService ingestionService;\n\n    public NotificationController(NotificationIngestionService ingestionService) {\n        this.ingestionService = ingestionService;\n    }\n\n    @PostMapping(\"/send\")\n    public ResponseEntity<SendNotificationResponse> send(\n            @RequestBody SendNotificationRequest request) {\n        SendNotificationResponse response = ingestionService.ingest(request);\n        return ResponseEntity.status(HttpStatus.ACCEPTED).body(response);\n    }\n}"
