          code: "/*\n * ======================== ENTITY-RELATIONSHIP DIAGRAM ========================\n *\n * +----------------------------------+ 1       * +----------------------------------+\n * |       channels (Postgres)        |-----------|     channel_members (Postgres)   |\n * +----------------------------------+           +----------------------------------+\n * | PK channel_id (BIGINT)           |           | PK channel_id (BIGINT)           |\n * |    channel_type (ENUM: DM, GRP)  |           | PK user_id (BIGINT)              |\n * |    name (VARCHAR(128))           |           |    role (ENUM: ADMIN, MEMBER)    |\n * |    member_count (INT)            |           |    last_read_msg_id (BIGINT)     |\n * |    created_at (INSTANT)          |           |    joined_at (INSTANT)           |\n * +----------------+-----------------+           +----------------------------------+\n *                  | 1\n *                  | 0..* (Sharded by channel_id + bucket)\n * +----------------+-----------------+           +----------------------------------+\n * |  channel_messages (Cassandra)    |           |   redis_session_registry (RAM)   |\n * +----------------------------------+           +----------------------------------+\n * | PK channel_id (BIGINT)           |           | PK \"sess:{user_id}\"              |\n * | PK bucket_yyyymm (INT)           |           |    HashField: device_id          |\n * | CK message_id (BIGINT DESC)      |           |    HashValue: gateway_node_id    |\n * |    sender_id (BIGINT)            |           |    last_seen_ms (INT64)          |\n * |    client_msg_uuid (UUID)        |           +----------------------------------+\n * |    content (TEXT)                |\n * |    media_url (VARCHAR(512))      |\n * |    created_at (TIMESTAMP)        |\n * +----------------------------------+\n */\n\npackage com.sdi.chat.domain;\n\nimport java.time.Instant;\nimport java.util.List;\n\npublic enum FrameType {\n    SEND_MSG,       // Client -> Gateway: User sends a message\n    SERVER_ACK,     // Gateway -> Sender: Message persisted with canonical messageId\n    NEW_MSG,        // Gateway -> Recipient: Real-time incoming message push\n    READ_RECEIPT,   // Client <-> Gateway: Watermark update (lastReadMessageId)\n    SYNC_HISTORY,   // Client -> Gateway: Fetch missed messages > lastSeenMessageId\n    HEARTBEAT       // Client <-> Gateway: Keepalive ping/pong every 30s\n}\n\n// --- WebSocket Wire Frame (Serialized via Protobuf or Jackson JSON) ---\npublic record WebSocketFrame(\n    FrameType type,\n    String clientMsgUuid,       // Client-generated idempotency key\n    long channelId,\n    long messageId,             // Server-assigned 64-bit Snowflake ID\n    long senderId,\n    String content,\n    String mediaUrl,\n    long timestampMs\n) {}\n\n// --- Cassandra Table Entity: PRIMARY KEY ((channel_id, bucket_yyyymm), message_id) ---\npublic record ChatMessageEntity(\n    long channelId,\n    int bucketYyyymm,           // e.g., 202609 (Prevents >100MB wide partitions)\n    long messageId,             // Snowflake ID (Clustering Key DESC)\n    long senderId,\n    String clientMsgUuid,\n    String content,\n    String mediaUrl,\n    Instant createdAt\n) {}\n\n// --- Internal gRPC Contract between Chat Routing Service & Stateful Chat Gateways ---\npublic interface ChatGatewayRpcClient {\n    /**\n     * Pushes a real-time frame to a specific user's device held in memory on targetGatewayId.\n     * Returns true if the socket was open and written to; false if socket disconnected.\n     */\n    boolean pushFrameToDevice(String targetGatewayId, long userId, String deviceId, WebSocketFrame frame);\n}\n\n// --- REST Controller for Offline History Sync & Pre-Signed Media Uploads ---\npublic interface ChatHistoryRestApi {\n    // GET /api/v1/channels/{channelId}/messages?afterMessageId=72819281920&limit=100\n    List<ChatMessageEntity> syncMissedMessages(long channelId, long afterMessageId, int limit);\n}"
